"""Test edge cases for BulkDataURI fix."""

import json
import warnings
from pydicom.dataset import Dataset


def test_nested_sequences():
    """Test BulkDataURI in deeply nested sequences."""
    print("Testing deeply nested sequences with BulkDataURI...")

    # Create JSON with nested sequences
    json_data = {
        "00100010": {
            "vr": "PN",
            "Value": [{"Alphabetic": "Test^Patient"}]
        },
        "52009100": {
            "vr": "SQ",
            "Value": [
                {
                    "00209000": {
                        "vr": "SQ", 
                        "Value": [
                            {
                                "7fe00010": {
                                    "vr": "OW",
                                    "BulkDataURI": "http://example.com/deep_bulkdata"
                                }
                            }
                        ]
                    },
                    "00280002": {
                        "vr": "US",
                        "Value": [1]
                    }
                }
            ]
        }
    }

    json_string = json.dumps(json_data)

    handler_calls = []
    def bulk_data_handler(tag, vr, value):
        handler_calls.append((tag, vr, value))
        print(f"Handler called: tag={tag}, vr={vr}, value={value}")
        return b'nested_dummy_data'

    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")
        ds = Dataset.from_json(json_string, bulk_data_uri_handler=bulk_data_handler)

        warnings_count = len([warning for warning in w if "bulk data URI handler" in str(warning.message)])
        print(f"Warnings: {warnings_count}")
        print(f"Handler calls: {len(handler_calls)}")

        assert warnings_count == 0, f"Expected 0 warnings, got {warnings_count}"
        assert len(handler_calls) == 1, f"Expected 1 handler call, got {len(handler_calls)}"
        print("✅ Deep nesting test passed")


def test_mixed_elements():
    """Test mix of BulkDataURI and regular elements in SQ."""
    print("\nTesting mixed elements in SQ...")

    json_data = {
        "52009100": {
            "vr": "SQ",
            "Value": [
                {
                    "7fe00010": {
                        "vr": "OW",
                        "BulkDataURI": "http://example.com/bulkdata"
                    },
                    "00280002": {
                        "vr": "US",
                        "Value": [1]
                    },
                    "00100010": {
                        "vr": "PN",
                        "Value": [{"Alphabetic": "Test^Name"}]
                    }
                }
            ]
        }
    }

    json_string = json.dumps(json_data)

    handler_calls = []
    def bulk_data_handler(tag, vr, value):
        handler_calls.append((tag, vr, value))
        return b'mixed_dummy_data'

    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")
        ds = Dataset.from_json(json_string, bulk_data_uri_handler=bulk_data_handler)

        warnings_count = len([warning for warning in w if "bulk data URI handler" in str(warning.message)])
        print(f"Warnings: {warnings_count}")
        print(f"Handler calls: {len(handler_calls)}")

        # Check that non-BulkDataURI elements are processed normally
        sq_elem = ds[0x52009100]
        item = sq_elem.value[0]
        assert item[0x00280002].value == 1  # US element
        assert item[0x00100010].value == "Test^Name"  # PN element

        assert warnings_count == 0, f"Expected 0 warnings, got {warnings_count}"
        assert len(handler_calls) == 1, f"Expected 1 handler call, got {len(handler_calls)}"
        print("✅ Mixed elements test passed")


def test_no_handler_still_works():
    """Test that the fix doesn't break the case with no handler."""
    print("\nTesting backward compatibility (no handler)...")

    json_data = {
        "52009100": {
            "vr": "SQ",
            "Value": [
                {
                    "7fe00010": {
                        "vr": "OW",
                        "BulkDataURI": "http://example.com/bulkdata"
                    }
                }
            ]
        }
    }

    json_string = json.dumps(json_data)

    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")
        ds = Dataset.from_json(json_string)  # No handler

        warnings_count = len([warning for warning in w if "bulk data URI handler" in str(warning.message)])
        print(f"Warnings: {warnings_count}")

        assert warnings_count == 1, f"Expected 1 warning, got {warnings_count}"
        # Check that the element value is None (empty value for VR)
        sq_elem = ds[0x52009100]
        item = sq_elem.value[0]
        assert item[0x7fe00010].value is None
        print("✅ Backward compatibility test passed")


if __name__ == "__main__":
    test_nested_sequences()
    test_mixed_elements()
    test_no_handler_still_works()
    print("\n🎉 All edge case tests passed!")"}

